interface ReplyDraft {
  id: string;
  authorLabel: string;
  preview: string;
}

/** Gmail-style "Undo Send" delay: an outgoing message sits in a cancellable
 *  pending state for this long before the real WAHA request fires. */
const UNDO_SEND_DELAY_MS = 10_000;

/** A queued-but-not-yet-sent message, plus the timers driving its countdown. */
interface PendingSend {
  id: string;
  conversation: Conversation;
  data: PendingSendData;
  secondsLeft: number;
}

function renderTemplateBody(body: string, params: string[]): string {
  return body.replace(/\{\{(\d+)\}\}/g, (_, raw) => {
    const idx = Number(raw) - 1;
    return params[idx] ?? `{{${raw}}}`;
  });
}

interface MessageThreadProps {
  conversation: Conversation | null;
  contact: Contact | null;
  messages: Message[];
  onMessagesLoaded: (messages: Message[]) => void;
  onNewMessage: (message: Message) => void;
  onUpdateMessage: (id: string, updates: Partial<Message>) => void;
  onStatusChange: (
    conversationId: string,
    status: ConversationStatus,
    outcomeTag?: Tag,
  ) => void;
  onAssignChange: (
    conversationId: string,
    assignedAgentId: string | null,
  ) => void;
  /**
   * On mobile, the thread is shown full-screen with the conversation list
   * hidden. This callback lets the page deselect the active conversation
   * and reveal the list again. Rendered as a back-arrow in the header on
   * mobile only.
   */
  onBack?: () => void;
  /**
   * Increment to force the messages + reactions fetch effects to refire.
   * Parent bumps this on realtime reconnect / tab visibility → visible
   * so the open thread catches up on any events sent while the WS was
   * disconnected or the tab was throttled. Optional so existing callers
   * keep working.
   */
  resyncToken?: number;
  /**
   * Fired by the manual-refresh button in the thread header. The parent
   * typically bumps the same `resyncToken` it controls — this gives the
   * user a way to force a refetch when they suspect realtime missed an
   * event (or they're impatient). Optional so existing callers keep
   * working; the button is only rendered when this is provided.
   */
  onRefresh?: () => void;
  /**
   * Desktop-only contact-panel toggle. The page owns the open/closed
   * state (it's the one that renders the sidebar), so the thread just
   * reflects it and asks the page to flip it. Both optional so existing
   * callers keep working; the toggle button only renders when
   * `onToggleContactPanel` is wired up.
   */
  contactPanelOpen?: boolean;
  onToggleContactPanel?: () => void;
  whatsappProvider?: string;
  onDeleteConversation?: (conversationId: string) => Promise<void>;
}

function formatDateSeparator(dateStr: string): string {
  const date = new Date(dateStr);
  if (isToday(date)) return "Hoje";
  if (isYesterday(date)) return "Ontem";
  return format(date, "d 'de' MMMM 'de' yyyy");
}

function groupMessagesByDate(messages: Message[]) {
  const groups: { date: string; messages: Message[] }[] = [];
  let currentDate = "";

  for (const msg of messages) {
    const day = format(new Date(msg.created_at), "yyyy-MM-dd");
    if (day !== currentDate) {
      currentDate = day;
      groups.push({ date: msg.created_at, messages: [msg] });
    } else {
      groups[groups.length - 1].messages.push(msg);
    }
  }

  return groups;
}

const STATUS_OPTIONS: { label: string; value: ConversationStatus; color: string }[] = [
  { label: "Aberto", value: "open", color: "text-primary" },
  { label: "Pendente", value: "pending", color: "text-amber-400" },
  { label: "Fechado", value: "closed", color: "text-muted-foreground" },
];

/**
 * WhatsApp-style doodle background applied to the chat area (both the
 * active thread and the empty state). The SVG tile lives at
 * `/public/inbox-doodle.svg`; the slate-950 colour sits underneath so
 * the doodles read as a subtle pattern rather than a stark grid.
 *
 * Defined once at module scope so the two render paths can't drift —
 * if we ever switch the asset, both spots update together.
 */
const DOODLE_BG_CLASSES =
  "bg-background bg-[url('/inbox-doodle.svg')] bg-repeat";

export function MessageThread({
  conversation,
  contact,
  messages,
  onMessagesLoaded,
  onNewMessage,
  onUpdateMessage,
  onStatusChange,
  onAssignChange,
  onBack,
  resyncToken = 0,
  onRefresh,
  contactPanelOpen,
  onToggleContactPanel,
  whatsappProvider = "meta",
  onDeleteConversation,
}: MessageThreadProps) {
  const { user } = useAuth();
  const [voipSession, setVoipSession] = useState<string>("default");

  useEffect(() => {
    // Fetch the active session name for VoIP routing
    fetch("/api/whatsapp/config")
      .then((res) => res.json())
      .then((data) => {
        if (data && data.provider === "waha" && data.phone_info?.id) {
          setVoipSession(data.phone_info.id);
        } else if (data && data.waha_session) {
          setVoipSession(data.waha_session);
        }
      })
      .catch((err) => console.warn("VoIP config fetch failed, using default:", err));
  }, []);

  const {
    activeCall,
    incomingCall,
    audioStream,
    startOutboundCall,
    acceptInboundCall,
    rejectInboundCall,
    endActiveCall,
  } = useVoipCall(voipSession);

  const { getPresence, getRow, now } = usePresence();
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const [templateModalOpen, setTemplateModalOpen] = useState(false);
  const [outcomeTagPickerOpen, setOutcomeTagPickerOpen] = useState(false);
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const [reactions, setReactions] = useState<MessageReaction[]>([]);
  // Purely visual spin state for the manual-refresh button. The actual
  // refetch is fire-and-forget through `onRefresh` (which bumps the
  // parent's resyncToken); the 700ms spin is just feedback so the click
  // doesn't feel like a no-op. Cleared via the timer ref on unmount.
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const refreshTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(() => {
    return () => {
      if (refreshTimerRef.current !== null) {
        clearTimeout(refreshTimerRef.current);
      }
    };
  }, []);
  const handleRefreshClick = useCallback(() => {
    if (isRefreshing || !onRefresh) return;
    setIsRefreshing(true);
    onRefresh();
    refreshTimerRef.current = setTimeout(() => {
      setIsRefreshing(false);
      refreshTimerRef.current = null;
    }, 700);
  }, [isRefreshing, onRefresh]);
  const handleDeleteClick = useCallback(async () => {
    if (!conversation || !onDeleteConversation) return;
    const confirmed = window.confirm("Deseja mesmo excluir esta conversa e todas as suas mensagens?");
    if (!confirmed) return;
    setIsDeleting(true);
    try {
      await onDeleteConversation(conversation.id);
    } finally {
      setIsDeleting(false);
    }
  }, [conversation, onDeleteConversation]);

  const [replyTo, setReplyTo] = useState<ReplyDraft | null>(null);

  // Profiles are bounded by RLS to rows the current user is allowed to
  // see — today that's just the current user, but the dropdown keeps the
  // shape ready for shared-team workspaces without a refactor.
  useEffect(() => {
    let cancelled = false;
    const supabase = createClient();
    supabase
      .from("profiles")
      .select("*")
      .order("full_name")
      .then(({ data, error }) => {
        if (cancelled) return;
        if (error) {
          console.error("Failed to fetch profiles:", error);
          return;
        }
        setProfiles((data as Profile[]) ?? []);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  // 24-hour session timer
  const sessionInfo = useMemo(() => {
    if (!messages.length) return { expired: false, remaining: "" };

    // If the provider is waha, or the conversation is associated with a WAHA session, the session never expires
    if (whatsappProvider === "waha" || !!conversation?.waha_session) {
      return { expired: false, remaining: "" };
    }

    // Find last customer message
    const lastCustomerMsg = [...messages]
      .reverse()
      .find((m) => m.sender_type === "customer");

    if (!lastCustomerMsg) return { expired: true, remaining: "Sem mensagens do cliente" };

    const hoursSince = differenceInHours(new Date(), new Date(lastCustomerMsg.created_at));
    const expired = hoursSince >= 24;

    if (expired) {
      return { expired: true, remaining: "Expirada" };
    }

    const hoursLeft = 24 - hoursSince;
    const remaining =
      hoursLeft >= 1
        ? `${Math.floor(hoursLeft)}h restantes`
        : `${Math.floor(hoursLeft * 60)}m restantes`;

    return { expired, remaining };
  }, [messages, whatsappProvider, conversation?.waha_session]);

  // Store latest callback in a ref so fetchMessages doesn't need to
  // depend on `onMessagesLoaded` — otherwise parent re-renders cause
  // fetchMessages to change → useEffect re-fires → refetch → realtime
  // UPDATE on conversations.unread_count → parent re-renders → LOOP.
  // The ref is written inside an effect so the mutation doesn't happen
  // during render (React 19 refs rule); consumers only read `.current`
  // inside the async fetch completion, which runs after the render.
  const onMessagesLoadedRef = useRef(onMessagesLoaded);
  useEffect(() => {
    onMessagesLoadedRef.current = onMessagesLoaded;
  });

  const conversationId = conversation?.id;
  const hasUnread = (conversation?.unread_count ?? 0) > 0;

  // Fetch messages whenever the selected conversation changes. Kept
  // separate from the unread-reset effect so that incoming messages
  // arriving while the thread is open don't trigger a full refetch —
  // they only flip hasUnread, which only the reset effect listens to.
  useEffect(() => {
    if (!conversationId) return;

    const supabase = createClient();
    let cancelled = false;

    (async () => {
      setLoading(true);

      const { data, error } = await supabase
        .from("messages")
        .select("*")
        .eq("conversation_id", conversationId)
        .order("created_at", { ascending: true });

      if (cancelled) return;

      if (error) {
        console.error("Failed to fetch messages:", error);
      } else {
        onMessagesLoadedRef.current(data ?? []);
      }

      if (!cancelled) setLoading(false);
    })();

    return () => {
      cancelled = true;
    };
    // `resyncToken` is included so the parent can force a refetch when
    // the realtime channel reconnects or the tab regains focus —
    // realtime is best-effort and any message events sent while the WS
    // was disconnected or throttled are otherwise lost.
  }, [conversationId, resyncToken]);

  // Reactions fetch — pulls the current state from the DB. Kept separate
  // from the channel subscription below so a `resyncToken` bump just
  // refetches the rows without also tearing down and rebuilding the
  // realtime channel.
  useEffect(() => {
    if (!conversationId) {
      setReactions([]);
      return;
    }
    const supabase = createClient();
    let cancelled = false;

    (async () => {
      const { data, error } = await supabase
        .from("message_reactions")
        .select("*")
        .eq("conversation_id", conversationId);
      if (cancelled) return;
      if (error) {
        console.error("Failed to fetch reactions:", error);
        return;
      }
      setReactions((data as MessageReaction[]) ?? []);
    })();

    return () => {
      cancelled = true;
    };
  }, [conversationId, resyncToken]);

  // Reactions realtime subscription per conversation. Subscribing here
  // (not at the page level) keeps the channel scoped to the visible
  // conversation and avoids cross-conversation chatter on a busy inbox.
  useEffect(() => {
    if (!conversationId) return;
    const supabase = createClient();

    const channel = supabase
      .channel(`reactions:${conversationId}`)
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "message_reactions",
          filter: `conversation_id=eq.${conversationId}`,
        },
        (payload) => {
          const row = payload.new as MessageReaction;
          setReactions((prev) => {
            if (prev.some((r) => r.id === row.id)) return prev;
            // Swap any matching optimistic temp row for the real one so
            // the pill doesn't double up after a successful POST.
            const tempIdx = prev.findIndex(
              (r) =>
                r.id.startsWith("temp-") &&
                r.message_id === row.message_id &&
                r.actor_type === row.actor_type &&
                r.actor_id === row.actor_id,
            );
            if (tempIdx >= 0) {
              const copy = prev.slice();
              copy[tempIdx] = row;
              return copy;
            }
            return [...prev, row];
          });
        },
      )
      .on(
        "postgres_changes",
        {
          event: "UPDATE",
          schema: "public",
          table: "message_reactions",
          filter: `conversation_id=eq.${conversationId}`,
        },
        (payload) => {
          const row = payload.new as MessageReaction;
          setReactions((prev) => prev.map((r) => (r.id === row.id ? row : r)));
        },
      )
      .on(
        "postgres_changes",
        {
          event: "DELETE",
          schema: "public",
          table: "message_reactions",
          filter: `conversation_id=eq.${conversationId}`,
        },
        (payload) => {
          const old = payload.old as Partial<MessageReaction>;
          if (!old?.id) return;
          setReactions((prev) => prev.filter((r) => r.id !== old.id));
        },
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [conversationId]);

  // Clear any in-progress reply draft when the active conversation changes —
  // a quote pulled from conversation A shouldn't bleed into conversation B.
  useEffect(() => {
    setReplyTo(null);
  }, [conversationId]);

  // Reset the server-side unread_count to 0 whenever an unread count
  // surfaces on the active conversation — covers both (a) opening a
  // conversation that had unread messages and (b) new messages arriving
  // while the user is already viewing the thread (webhook server-bumps
  // unread_count to N+1; the realtime UPDATE propagates it into the
  // client, which re-runs this effect and flips it back to 0).
  //
  // Guarding on hasUnread prevents the eq-update loop: once unread_count
  // is 0 the condition is false, so no further UPDATE is issued.
  useEffect(() => {
    if (!conversationId || !hasUnread) return;
    const supabase = createClient();
    supabase
      .from("conversations")
      .update({ unread_count: 0 })
      .eq("id", conversationId)
      .then(({ error }) => {
        if (error) console.error("Failed to reset unread_count:", error);
      });
  }, [conversationId, hasUnread]);

  // Auto-scroll to bottom on new messages
  useEffect(() => {
    if (scrollRef.current) {
      const el = scrollRef.current;
      el.scrollTop = el.scrollHeight;
    }
  }, [messages]);

  // ---- Undo-Send: commit helpers ------------------------------------
  //
  // These perform the real WAHA request. They're parameterized on a
  // *snapshotted* conversation (captured when the message was queued,
  // not read from the `conversation` prop) so a flush that fires after
  // the agent has switched threads still targets the right conversation.
  // `silent` skips the optimistic-bubble bookkeeping for that case: the
  // shared `messages` list only ever holds the currently-open thread's
  // rows, so touching it for a conversation the agent already navigated
  // away from would leak a foreign message into the new thread's view.

  const commitTextSend = useCallback(
    async (
      conv: Conversation,
      text: string,
      replyToId: string | undefined,
      opts: { silent: boolean },
    ) => {
      const tempId = `temp-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

      if (!opts.silent) {
        const optimisticMsg: Message = {
          id: tempId,
          conversation_id: conv.id,
          sender_type: "agent",
          content_type: "text",
          content_text: text,
          status: "sending",
          created_at: new Date().toISOString(),
          reply_to_message_id: replyToId,
        };
        onNewMessage(optimisticMsg);
      }

      try {
        const res = await fetch("/api/whatsapp/send", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            conversation_id: conv.id,
            message_type: "text",
            content_text: text,
            reply_to_message_id: replyToId,
          }),
        });

        const payload = await res.json().catch(() => ({}));

        if (!res.ok) {
          const reason = payload?.error || `HTTP ${res.status}`;
          console.error("Failed to send message:", reason);
          toast.error(`Falha ao enviar: ${reason}`);
          if (!opts.silent) onUpdateMessage(tempId, { status: "failed" });
          return;
        }

        // Success — the realtime INSERT event will replace the temp bubble
        // with the real DB row. If realtime hasn't arrived yet, at least
        // flip status to 'sent' so the UI stops showing "sending".
        if (!opts.silent) onUpdateMessage(tempId, { status: "sent" });
      } catch (err) {
        console.error("Failed to send message:", err);
        const reason = err instanceof Error ? err.message : "erro de rede";
        toast.error(`Falha ao enviar: ${reason}`);
        if (!opts.silent) onUpdateMessage(tempId, { status: "failed" });
      }
    },
    [onNewMessage, onUpdateMessage],
  );

  const commitMediaSend = useCallback(
    async (conv: Conversation, payload: SendMediaPayload, opts: { silent: boolean }) => {
      // Documents show their filename in our own bubble (and to the
      // recipient as the Meta caption when no caption was typed); other
      // kinds use the caption as-is. Audio carries no caption.
      const contentText =
        payload.kind === "document"
          ? payload.caption || payload.filename || "Document"
          : payload.caption;

      const tempId = `temp-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

      if (!opts.silent) {
        const optimisticMsg: Message = {
          id: tempId,
          conversation_id: conv.id,
          sender_type: "agent",
          content_type: payload.kind,
          content_text: contentText,
          media_url: payload.mediaUrl,
          status: "sending",
          created_at: new Date().toISOString(),
          reply_to_message_id: payload.replyToId,
        };
        onNewMessage(optimisticMsg);
      }

      try {
        const res = await fetch("/api/whatsapp/send", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            conversation_id: conv.id,
            message_type: payload.kind,
            media_url: payload.mediaUrl,
            content_text: contentText,
            filename: payload.filename,
            reply_to_message_id: payload.replyToId,
          }),
        });

        const data = await res.json().catch(() => ({}));

        if (!res.ok) {
          const reason = data?.error || `HTTP ${res.status}`;
          console.error("Failed to send media:", reason);
          toast.error(`Falha ao enviar: ${reason}`);
          if (!opts.silent) onUpdateMessage(tempId, { status: "failed" });
          // The upload never reached the recipient — GC the orphaned
          // object rather than leaving it in the public bucket forever.
          void deleteAccountMedia(CHAT_MEDIA_BUCKET, payload.path).catch(() => {});
          return;
        }

        if (!opts.silent) onUpdateMessage(tempId, { status: "sent" });
      } catch (err) {
        console.error("Failed to send media:", err);
        const reason = err instanceof Error ? err.message : "erro de rede";
        toast.error(`Falha ao enviar: ${reason}`);
        if (!opts.silent) onUpdateMessage(tempId, { status: "failed" });
        void deleteAccountMedia(CHAT_MEDIA_BUCKET, payload.path).catch(() => {});
      }
    },
    [onNewMessage, onUpdateMessage],
  );

  const handleStatusChange = useCallback(
    async (status: ConversationStatus, outcomeTag?: Tag) => {
      if (!conversation) return;

      const updates: { status: ConversationStatus; outcome_tag_id?: string } = {
        status,
      };
      if (outcomeTag) updates.outcome_tag_id = outcomeTag.id;

      const supabase = createClient();
      await supabase.from("conversations").update(updates).eq("id", conversation.id);

      onStatusChange(conversation.id, status, outcomeTag);
    },
    [conversation, onStatusChange]
  );

  // Closing a conversation requires picking an outcome tag first — the
  // status update itself only happens once a tag is chosen (or the
  // status is anything other than "closed").
  const handleStatusOptionClick = useCallback(
    (status: ConversationStatus) => {
      if (status === "closed") {
        setOutcomeTagPickerOpen(true);
        return;
      }
      void handleStatusChange(status);
    },
    [handleStatusChange]
  );

  const handleOutcomeTagSelect = useCallback(
    (tag: Tag) => {
      setOutcomeTagPickerOpen(false);
      void handleStatusChange("closed", tag);
    },
    [handleStatusChange]
  );

  const handleOpenTemplates = useCallback(() => {
    setTemplateModalOpen(true);
  }, []);

  const handleSendTemplate = useCallback(
    async (
      template: MessageTemplate,
      values: {
        body: string[];
        headerText?: string;
        buttonParams?: Record<number, string>;
      },
    ) => {
      if (!conversation) return;

      const renderedBody = renderTemplateBody(template.body_text, values.body);
      const tempId = `temp-${Date.now()}`;

      const optimisticMsg: Message = {
        id: tempId,
        conversation_id: conversation.id,
        sender_type: "agent",
        content_type: "template",
        content_text: renderedBody,
        template_name: template.name,
        status: "sending",
        created_at: new Date().toISOString(),
      };
      onNewMessage(optimisticMsg);

      try {
        const res = await fetch("/api/whatsapp/send", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            conversation_id: conversation.id,
            message_type: "template",
            template_name: template.name,
            template_language: template.language,
            // Structured params drive the new send-builder path
            // (header media + URL button substitution). Body values
            // are mirrored under both shapes so the route can fall
            // back if the template row isn't found locally.
            template_message_params: {
              body: values.body,
              headerText: values.headerText,
              buttonParams: values.buttonParams,
            },
            template_params: values.body,
            content_text: renderedBody,
          }),
        });

        const payload = await res.json().catch(() => ({}));

        if (!res.ok) {
          const reason = payload?.error || `HTTP ${res.status}`;
          console.error("Failed to send template:", reason);
          toast.error(`Falha ao enviar template: ${reason}`);
          onUpdateMessage(tempId, { status: "failed" });
          return;
        }

        onUpdateMessage(tempId, { status: "sent" });
      } catch (err) {
        console.error("Failed to send template:", err);
        const reason = err instanceof Error ? err.message : "erro de rede";
        toast.error(`Falha ao enviar template: ${reason}`);
        onUpdateMessage(tempId, { status: "failed" });
      }
    },
    [conversation, onNewMessage, onUpdateMessage],
  );

  // Build a quick id → Message map so reply quotes can be rendered without
  // an extra fetch — the thread already holds the full conversation.
  const messagesById = useMemo(() => {
    const map = new Map<string, Message>();
    for (const m of messages) map.set(m.id, m);
    return map;
  }, [messages]);

  // Bucket reactions by their target message_id for O(1) per-bubble lookup.
  const reactionsByMessageId = useMemo(() => {
    const map = new Map<string, MessageReaction[]>();
    for (const r of reactions) {
      const bucket = map.get(r.message_id);
      if (bucket) bucket.push(r);
      else map.set(r.message_id, [r]);
    }
    return map;
  }, [reactions]);

  const contactDisplayName = contact?.name || contact?.phone || "Cliente";

  // Author label for a quoted message: "You" when we sent the parent,
  // contact name when the customer sent it.
  const authorLabelFor = useCallback(
    (m: Message): string => {
      const isAgentMsg =
        m.sender_type === "agent" || m.sender_type === "bot";
      return isAgentMsg ? "Você" : contactDisplayName;
    },
    [contactDisplayName],
  );

  const handleStartReply = useCallback(
    (msg: Message) => {
      setReplyTo({
        id: msg.id,
        authorLabel: authorLabelFor(msg),
        preview: buildReplyPreview(msg),
      });
    },
    [authorLabelFor],
  );

  // ---- Undo-Send: pending queue ---------------------------------------
  //
  // `pendingSends` drives the countdown bubbles' render; `pendingSendsRef`
  // mirrors it synchronously (updated inside the same setState call, not a
  // follow-up effect) so lookups from the queue's callbacks — which fire
  // from outside React's render cycle — always read the current list
  // instead of a stale one from the last completed render. The actual
  // timers (and the double-commit guard) live in `pendingQueueRef`, a
  // framework-agnostic scheduler unit-tested on its own — see
  // src/lib/inbox/pending-send-queue.test.ts.
  const [pendingSends, setPendingSends] = useState<PendingSend[]>([]);
  const pendingSendsRef = useRef<PendingSend[]>([]);
  const pendingQueueRef = useRef(createPendingSendQueue({ delayMs: UNDO_SEND_DELAY_MS }));
  const [recall, setRecall] = useState<RecallDraft | null>(null);

  const updatePendingSends = useCallback(
    (updater: (prev: PendingSend[]) => PendingSend[]) => {
      setPendingSends((prev) => {
        const next = updater(prev);
        pendingSendsRef.current = next;
        return next;
      });
    },
    [],
  );

  // Fires when a pending item's delay elapses, or when it's flushed early
  // (conversation switch / unmount). `silent` skips the optimistic-bubble
  // bookkeeping on flush — see the comment on `commitTextSend` above.
  const commitPendingById = useCallback(
    (id: string, opts?: { silent?: boolean }) => {
      const entry = pendingSendsRef.current.find((p) => p.id === id);
      updatePendingSends((prev) => prev.filter((p) => p.id !== id));
      if (!entry) return;
      if (entry.data.kind === "text") {
        void commitTextSend(entry.conversation, entry.data.text, entry.data.replyToId, {
          silent: !!opts?.silent,
        });
      } else {
        void commitMediaSend(entry.conversation, entry.data.payload, {
          silent: !!opts?.silent,
        });
      }
    },
    [updatePendingSends, commitTextSend, commitMediaSend],
  );

  const enqueuePending = useCallback(
    (conv: Conversation, data: PendingSendData) => {
      const id = `pending-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
      const entry: PendingSend = {
        id,
        conversation: conv,
        data,
        secondsLeft: Math.ceil(UNDO_SEND_DELAY_MS / 1000),
      };
      updatePendingSends((prev) => [...prev, entry]);

      pendingQueueRef.current.schedule(id, {
        onTick: (secondsLeft) => {
          updatePendingSends((prev) =>
            prev.map((p) => (p.id === id ? { ...p, secondsLeft } : p)),
          );
        },
        onCommit: (reason) => commitPendingById(id, { silent: reason === "flush" }),
      });
    },
    [updatePendingSends, commitPendingById],
  );

  // "Desfazer" — drop the pending message, GC any staged (unsent) media.
  const cancelPending = useCallback(
    (id: string) => {
      const entry = pendingSendsRef.current.find((p) => p.id === id);
      pendingQueueRef.current.cancel(id);
      updatePendingSends((prev) => prev.filter((p) => p.id !== id));
      if (entry?.data.kind === "media") {
        void deleteAccountMedia(CHAT_MEDIA_BUCKET, entry.data.payload.path).catch(() => {});
      }
    },
    [updatePendingSends],
  );

  // "Editar" — drop the pending message and hand its content back to the
  // composer (and restore the reply-quote context, if any) instead of
  // sending it.
  const editPending = useCallback(
    (id: string) => {
      const entry = pendingSendsRef.current.find((p) => p.id === id);
      if (!entry) return;
      pendingQueueRef.current.cancel(id);
      updatePendingSends((prev) => prev.filter((p) => p.id !== id));

      const replyToId =
        entry.data.kind === "text" ? entry.data.replyToId : entry.data.payload.replyToId;
      if (replyToId) {
        const parent = messagesById.get(replyToId);
        if (parent) {
          setReplyTo({
            id: parent.id,
            authorLabel: authorLabelFor(parent),
            preview: buildReplyPreview(parent),
          });
        }
      }

      if (entry.data.kind === "text") {
        setRecall({ id, text: entry.data.text });
      } else {
        const { payload } = entry.data;
        setRecall({
          id,
          media: {
            kind: payload.kind,
            mediaUrl: payload.mediaUrl,
            path: payload.path,
            filename: payload.filename ?? "",
            caption: payload.caption ?? "",
          },
        });
      }
    },
    [updatePendingSends, messagesById, authorLabelFor],
  );

  const handleRecallHandled = useCallback(() => setRecall(null), []);

  // Flush when the agent switches to a different conversation — the timers
  // would otherwise keep running against a thread that's no longer visible
  // (and, worse, get GC'd if the agent later closes the tab). `conversationId`
  // already exists above (the fetch-messages effect depends on it); this
  // effect only cares about the transition, not the initial mount.
  const prevConversationIdRef = useRef(conversationId);
  useEffect(() => {
    if (prevConversationIdRef.current !== conversationId) {
      pendingQueueRef.current.flushAll();
      prevConversationIdRef.current = conversationId;
    }
  }, [conversationId]);

  // Flush on unmount (navigating away from the Inbox entirely) — the worst
  // case becomes "sent a little early," never "silently lost."
  useEffect(() => {
    const queue = pendingQueueRef.current;
    return () => {
      queue.flushAll();
    };
  }, []);

  const handleSend = useCallback(
    (text: string, replyToId?: string) => {
      if (!conversation) return;
      setReplyTo(null);
      enqueuePending(conversation, { kind: "text", text, replyToId });
    },
    [conversation, enqueuePending],
  );

  const handleSendMedia = useCallback(
    (payload: SendMediaPayload) => {
      if (!conversation) return;
      setReplyTo(null);
      enqueuePending(conversation, { kind: "media", payload });
    },
    [conversation, enqueuePending],
  );

  // Single reaction-set primitive. emoji === "" removes; otherwise adds/swaps.
  // The "toggle" semantic (pill click) is computed at the call site where the
  // current reactions for the bubble are already in scope — keeps this
  // function dependency-free w.r.t. the reaction list.
  const postReaction = useCallback(
    async (messageId: string, emoji: string) => {
      if (!user?.id || !conversation) {
        console.warn("[reactions] missing user or conversation");
        return;
      }
      if (messageId.startsWith("temp-")) {
        toast.error("Aguarde a mensagem terminar de ser enviada");
        return;
      }

      const convId = conversation.id;
      const userId = user.id;
      let snapshot: MessageReaction[] = [];

      // Functional updater — captures the freshest reactions list, never a
      // stale closure. Snapshot stored for rollback on POST failure.
      setReactions((prev) => {
        snapshot = prev;
        const own = prev.find(
          (r) =>
            r.message_id === messageId &&
            r.actor_type === "agent" &&
            r.actor_id === userId,
        );
        if (emoji === "") return own ? prev.filter((r) => r !== own) : prev;
        if (own) return prev.map((r) => (r === own ? { ...own, emoji } : r));
        return [
          ...prev,
          {
            id: `temp-${Date.now()}`,
            message_id: messageId,
            conversation_id: convId,
            actor_type: "agent",
            actor_id: userId,
            emoji,
            created_at: new Date().toISOString(),
          },
        ];
      });

      try {
        const res = await fetch("/api/whatsapp/react", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ message_id: messageId, emoji }),
        });
        if (!res.ok) {
          const payload = await res.json().catch(() => ({}));
          throw new Error(payload?.error || `HTTP ${res.status}`);
        }
      } catch (err) {
        const reason = err instanceof Error ? err.message : "erro de rede";
        toast.error(`Falha ao reagir: ${reason}`);
        setReactions(snapshot);
      }
    },
    [conversation, user?.id],
  );

  const handleAssignChange = useCallback(
    async (agentId: string | null) => {
      if (!conversation) return;

      const supabase = createClient();
      const assignedAgent = agentId ? profiles.find((p) => p.user_id === agentId) : undefined;
      const { error } = await assignConversationAgent(
        supabase,
        conversation.id,
        agentId,
        assignedAgent?.full_name,
      );

      if (error) {
        console.error("Failed to update assignment:", error);
        toast.error("Falha ao atualizar atribuição");
        return;
      }

      onAssignChange(conversation.id, agentId);
    },
    [conversation, onAssignChange, profiles],
  );

  // Empty state — same WhatsApp-style doodle background as the active
  // thread below, so swapping between empty/selected doesn't change the
  // pattern under the user's eye.
  if (!conversation || !contact) {
    return (
      <div className={cn("flex flex-1 flex-col items-center justify-center", DOODLE_BG_CLASSES)}>
        <div className="flex h-16 w-16 items-center justify-center rounded-full bg-muted">
          <MessageSquare className="h-8 w-8 text-muted-foreground" />
        </div>
        <h3 className="mt-4 text-sm font-medium text-muted-foreground">
          Selecione uma conversa
        </h3>
        <p className="mt-1 text-xs text-muted-foreground">
          Escolha uma conversa à esquerda para começar a enviar mensagens
        </p>
      </div>
    );
  }

  const displayName = contact.name || contact.phone;
  const messageGroups = groupMessagesByDate(messages);
  const currentStatus = STATUS_OPTIONS.find(
    (s) => s.value === conversation.status
  );
  const assignedAgentId = conversation.assigned_agent_id ?? null;
  const currentAssignee = profiles.find((p) => p.user_id === assignedAgentId);
  const assignLabel = assignedAgentId
    ? (currentAssignee?.full_name ?? "Atribuído")
    : "Atribuir";

  return (
    // `min-w-0` is load-bearing: the page already puts min-w-0 on the
    // thread's flex *wrapper* (issue #165), but this root keeps the
    // default `min-width: auto`, so a single wide message (long unbroken
    // URL/word) expands the whole thread past its flex share and the chat
    // paints on top of the contact sidebar at lg+ — outgoing bubbles get
    // clipped and the hover toolbar overlaps the Tags panel. Letting the
    // root shrink lets the bubbles' break-words / max-w caps apply.
    // Issue #257.
    <div className={cn("flex min-w-0 flex-1 flex-col", DOODLE_BG_CLASSES)}>
      {/* Header — solid card surface sits on top of the doodle so the
          name/avatar/dropdowns stay legible. */}
      <div className="flex items-center justify-between gap-2 border-b border-border bg-card px-3 py-3 sm:px-4">
        <div className="flex min-w-0 items-center gap-2 sm:gap-3">
          {/* Back-to-list button — mobile only. Hidden on lg+ where the
              conversation list is always visible next to the thread. */}
          {onBack && (
            <button
              type="button"
              onClick={onBack}
              aria-label="Voltar às conversas"
              className="flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-md text-muted-foreground hover:bg-muted hover:text-foreground lg:hidden"
            >
              <ArrowLeft className="h-5 w-5" />
            </button>
          )}
          <div className="flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-full bg-muted text-sm font-medium text-foreground overflow-hidden">
            {contact.avatar_url ? (
              <img
                src={contact.avatar_url}
                alt={displayName}
                className="h-9 w-9 rounded-full object-cover"
              />
            ) : (
              displayName.charAt(0).toUpperCase()
            )}
          </div>
          <div className="min-w-0">
            <div className="flex items-center gap-2">
              <h2 className="truncate text-sm font-semibold text-foreground">{displayName}</h2>
              {conversation.sentiment && conversation.sentiment !== "unknown" && (
                <span
                  className={cn(
                    "inline-flex items-center gap-1 rounded-full px-1.5 py-0.5 text-[10px] font-medium border select-none transition-all duration-200",
                    conversation.sentiment === "positive" && "bg-emerald-500/10 text-emerald-400 border-emerald-500/20",
                    conversation.sentiment === "negative" && "bg-rose-500/10 text-rose-400 border-rose-500/20",
                    conversation.sentiment === "neutral" && "bg-blue-500/10 text-blue-400 border-blue-500/20",
                    conversation.sentiment === "mixed" && "bg-amber-500/10 text-amber-400 border-amber-500/20"
                  )}
                  title={`Sentimento: ${conversation.sentiment}`}
                >
                  {conversation.sentiment === "positive" && "😊 Positivo"}
                  {conversation.sentiment === "negative" && "😡 Negativo"}
                  {conversation.sentiment === "neutral" && "😐 Neutro"}
                  {conversation.sentiment === "mixed" && "🤔 Misto"}
                </span>
              )}
            </div>
            <p className="truncate text-xs text-muted-foreground">{contact.phone}</p>
          </div>
          {/* Session timer badge — hidden on the narrowest phones so
              the name + back arrow keep their room. */}
          <Badge
            variant="outline"
            className={cn(
              "ml-1 hidden gap-1 border-border text-[10px] sm:inline-flex sm:ml-2",
              sessionInfo.expired ? "text-red-400" : "text-primary"
            )}
          >
            <Clock className="h-3 w-3" />
            {sessionInfo.remaining}
          </Badge>
        </div>

        <div className="flex items-center gap-2">
          {/* Contact-panel toggle — desktop only. The contact sidebar
              eats a chunk of horizontal width that crowds the thread on
              smaller laptops; this lets agents reclaim it when they just
              want to read and reply. Hidden on mobile, where the sidebar
              never renders as a permanent panel anyway. Issue #258. */}
          {onToggleContactPanel && (
            <button
              type="button"
              onClick={onToggleContactPanel}
              aria-label={
                contactPanelOpen ? "Ocultar painel de contato" : "Exibir painel de contato"
              }
              aria-pressed={contactPanelOpen}
              title={contactPanelOpen ? "Ocultar contato" : "Exibir contato"}
              className={cn(
                "hidden h-7 w-7 items-center justify-center rounded-md transition-colors hover:bg-muted hover:text-foreground lg:inline-flex",
                contactPanelOpen ? "text-primary" : "text-muted-foreground",
              )}
            >
              {contactPanelOpen ? (
                <PanelRightClose className="h-4 w-4" />
              ) : (
                <PanelRightOpen className="h-4 w-4" />
              )}
            </button>
          )}

          {/* Manual refresh — forces a refetch of the messages + the
              conversation list (the parent bumps its resyncToken). Useful
              when realtime missed an event or the agent just wants to be
              sure nothing's stale. Only rendered when the parent wires
              up `onRefresh`. */}
          {/* WhatsApp WebRTC VoIP Call Button */}
          {whatsappProvider === "waha" && contact?.phone && (
            <button
              type="button"
              onClick={() => startOutboundCall(contact.phone)}
              aria-label="Iniciar chamada de voz"
              title="Ligar pelo WhatsApp"
              className="inline-flex h-7 w-7 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-muted hover:text-emerald-400"
            >
              <Phone className="h-4 w-4" />
            </button>
          )}

          {onRefresh && (
            <button
              type="button"
              onClick={handleRefreshClick}
              disabled={isRefreshing}
              aria-label="Atualizar conversa"
              title="Atualizar"
              className={cn(
                "inline-flex h-7 w-7 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-muted hover:text-foreground disabled:opacity-60",
              )}
            >
              <RefreshCw
                className={cn("h-3.5 w-3.5", isRefreshing && "animate-spin")}
              />
            </button>
          )}

          {onDeleteConversation && conversation && (
            <button
              type="button"
              onClick={handleDeleteClick}
              disabled={isDeleting}
              aria-label="Deletar conversa"
              title="Deletar Conversa"
              className={cn(
                "inline-flex h-7 w-7 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-muted hover:text-red-400 disabled:opacity-60",
              )}
            >
              {isDeleting ? (
                <Loader2 className="h-3.5 w-3.5 animate-spin" />
              ) : (
                <Trash2 className="h-3.5 w-3.5" />
              )}
            </button>
          )}

          {/* Status dropdown */}
          <DropdownMenu>
            <DropdownMenuTrigger className={cn(
                  "inline-flex items-center justify-center h-7 gap-1 px-2 text-xs rounded-md hover:bg-muted",
                  currentStatus?.color ?? "text-muted-foreground"
                )}>
                {currentStatus?.label ?? "Status"}
                <ChevronDown className="h-3 w-3" />
            </DropdownMenuTrigger>
            <DropdownMenuContent
              align="end"
              className="border-border bg-popover"
            >
              {STATUS_OPTIONS.map((opt) => (
                <DropdownMenuItem
                  key={opt.value}
                  onClick={() => handleStatusOptionClick(opt.value)}
                  className={cn("text-sm", opt.color)}
                >
                  {opt.label}
                </DropdownMenuItem>
              ))}
            </DropdownMenuContent>
          </DropdownMenu>

          {conversation.status === "closed" && conversation.outcome_tag && (
            <Badge
              className="border-0 text-[10px]"
              style={{
                backgroundColor: `${conversation.outcome_tag.color}26`,
                color: conversation.outcome_tag.color,
              }}
            >
              {conversation.outcome_tag.name}
            </Badge>
          )}

          {/* Assign dropdown */}
          <DropdownMenu>
            <DropdownMenuTrigger
              className={cn(
                "inline-flex items-center justify-center h-7 gap-1 px-2 text-xs rounded-md hover:bg-muted",
                assignedAgentId ? "text-primary" : "text-muted-foreground"
              )}
            >
              <UserPlus className="h-3 w-3" />
              <span className="hidden sm:inline">{assignLabel}</span>
              <ChevronDown className="h-3 w-3" />
            </DropdownMenuTrigger>
            <DropdownMenuContent
              align="end"
              className="border-border bg-popover"
            >
              {profiles.length === 0 ? (
                <DropdownMenuItem disabled className="text-sm text-muted-foreground">
                  Nenhum membro disponível
                </DropdownMenuItem>
              ) : (
                profiles.map((p) => {
                  const isSelected = p.user_id === assignedAgentId;
                  const presence = getPresence(p.user_id);
                  return (
                    <DropdownMenuItem
                      key={p.id}
                      onClick={() => handleAssignChange(p.user_id)}
                      className={cn(
                        "text-sm",
                        isSelected ? "text-primary" : "text-popover-foreground"
                      )}
                    >
                      <PresenceDot
                        status={presence}
                        label={presenceLabel(
                          presence,
                          getRow(p.user_id)?.last_seen_at ?? null,
                          now
                        )}
                        className="mr-2"
                      />
                      <span className="flex-1">
                        {p.full_name}
                        {p.user_id === user?.id ? " (eu)" : ""}
                      </span>
                      {isSelected && <Check className="ml-2 h-3 w-3" />}
                    </DropdownMenuItem>
                  );
                })
              )}
              {assignedAgentId && (
                <>
                  <DropdownMenuSeparator className="bg-border" />
                  <DropdownMenuItem
                    onClick={() => handleAssignChange(null)}
                    className="text-sm text-muted-foreground"
                  >
                    Remover atribuição
                  </DropdownMenuItem>
                </>
              )}
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>

      {/* Messages Area */}
      <div ref={scrollRef} className="flex-1 overflow-y-auto px-4 py-4">
        {loading ? (
          <div className="flex items-center justify-center py-12">
            <div className="h-5 w-5 animate-spin rounded-full border-2 border-primary border-t-transparent" />
          </div>
        ) : messages.length === 0 && pendingSends.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-12">
            <p className="text-sm text-muted-foreground">Nenhuma mensagem ainda</p>
            <p className="text-xs text-muted-foreground">
              Envie um template para iniciar a conversa
            </p>
          </div>
        ) : (
          <div className="space-y-4">
            {messageGroups.map((group) => (
              <div key={group.date}>
                {/* Date separator */}
                <div className="mb-4 flex items-center justify-center">
                  <span className="rounded-full bg-muted px-3 py-1 text-[10px] font-medium text-muted-foreground">
                    {formatDateSeparator(group.date)}
                  </span>
                </div>
                {/* Messages */}
                <div className="space-y-2">
                  {group.messages.map((msg) => {
                    const parent = msg.reply_to_message_id
                      ? messagesById.get(msg.reply_to_message_id)
                      : null;
                    const reply = parent
                      ? {
                          authorLabel: authorLabelFor(parent),
                          preview: buildReplyPreview(parent),
                        }
                      : null;
                    const msgReactions = reactionsByMessageId.get(msg.id);
                    // Toggle is computed at the call site — `msgReactions`
                    // and `user?.id` are already in scope, no extra hook.
                    const handlePillToggle = (emoji: string) => {
                      const own = msgReactions?.find(
                        (r) =>
                          r.actor_type === "agent" &&
                          r.actor_id === user?.id,
                      );
                      const next = own?.emoji === emoji ? "" : emoji;
                      void postReaction(msg.id, next);
                    };
                    return (
                      <MessageActions
                        key={msg.id}
                        message={msg}
                        onReply={() => handleStartReply(msg)}
                        onReact={(emoji) => {
                          if (emoji) void postReaction(msg.id, emoji);
                        }}
                      >
                        <MessageBubble
                          message={msg}
                          reply={reply}
                          reactions={msgReactions}
                          currentUserId={user?.id}
                          onToggleReaction={handlePillToggle}
                        />
                      </MessageActions>
                    );
                  })}
                </div>
              </div>
            ))}
            {pendingSends.length > 0 && (
              <div className="space-y-2">
                {pendingSends.map((p) => (
                  <PendingSendBubble
                    key={p.id}
                    data={p.data}
                    secondsLeft={p.secondsLeft}
                    onUndo={() => cancelPending(p.id)}
                    onEdit={() => editPending(p.id)}
                  />
                ))}
              </div>
            )}
          </div>
        )}
      </div>

      {/* Composer */}
      <MessageComposer
        conversationId={conversation.id}
        sessionExpired={sessionInfo.expired}
        onSend={handleSend}
        onSendMedia={handleSendMedia}
        onOpenTemplates={handleOpenTemplates}
        replyTo={replyTo}
        onClearReply={() => setReplyTo(null)}
        recall={recall}
        onRecallHandled={handleRecallHandled}
      />

      <TemplatePicker
        open={templateModalOpen}
        onOpenChange={setTemplateModalOpen}
        onSelect={handleSendTemplate}
      />

      <OutcomeTagPicker
        open={outcomeTagPickerOpen}
        onOpenChange={setOutcomeTagPickerOpen}
        onSelect={handleOutcomeTagSelect}
      />

      {/* Real-time VoIP Call Popup Overlay */}
      <VoipCallOverlay
        activeCall={activeCall}
        incomingCall={incomingCall}
        audioStream={audioStream}
        contactName={displayName}
        onAccept={acceptInboundCall}
        onReject={rejectInboundCall}
        onHangup={endActiveCall}
      />
    </div>
  );
}
